const dropZone = document.getElementById('imageDropZone');
const productImage = document.getElementById('productImage');
const fileInput = document.getElementById('fileInput');
const addToCartBtn = document.getElementById('addToCartBtn');
const wishlistBtn = document.getElementById('wishlistBtn');

function loadImageFile(file) {
  if (!file || !file.type.startsWith('image/')) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    if (productImage) productImage.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

if (dropZone) {
  dropZone.addEventListener('dragover', function(e) {
    e.preventDefault();
    dropZone.classList.add('drag-over-1748000000');
  });

  dropZone.addEventListener('dragleave', function(e) {
    dropZone.classList.remove('drag-over-1748000000');
  });

  dropZone.addEventListener('drop', function(e) {
    e.preventDefault();
    dropZone.classList.remove('drag-over-1748000000');
    const file = e.dataTransfer.files && e.dataTransfer.files[0];
    if (file) loadImageFile(file);
  });
}

if (fileInput) {
  fileInput.addEventListener('change', function(e) {
    const file = e.target.files && e.target.files[0];
    if (file) loadImageFile(file);
  });
}

if (addToCartBtn) {
  addToCartBtn.addEventListener('click', function() {
    addToCartBtn.textContent = '✓ Added!';
    addToCartBtn.classList.add('added-1748000000');
    setTimeout(function() {
      addToCartBtn.textContent = '🛒 Add to Cart';
      addToCartBtn.classList.remove('added-1748000000');
    }, 2000);
  });
}

if (wishlistBtn) {
  wishlistBtn.addEventListener('click', function() {
    const isLiked = wishlistBtn.classList.toggle('liked-1748000000');
    wishlistBtn.textContent = isLiked ? '♥' : '♡';
  });
}

