* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  padding: 20px;
}

.container-1748000000 {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.product-card-1748000000 {
  background: #ffffff;
  border-radius: 24px;
  overflow: hidden;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 30px 60px rgba(0,0,0,0.25);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.product-card-1748000000:hover {
  transform: translateY(-6px);
  box-shadow: 0 40px 80px rgba(0,0,0,0.3);
}

/* Image Drop Zone */
.image-drop-zone-1748000000 {
  position: relative;
  width: 100%;
  height: 280px;
  overflow: hidden;
  cursor: pointer;
  background: #f0f0f0;
}

.image-drop-zone-1748000000.drag-over-1748000000 {
  outline: 3px dashed #667eea;
  outline-offset: -6px;
}

.image-drop-zone-1748000000.drag-over-1748000000 .drop-overlay-1748000000 {
  opacity: 1;
  pointer-events: all;
}

.drop-overlay-1748000000 {
  position: absolute;
  inset: 0;
  background: rgba(102, 126, 234, 0.85);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  z-index: 10;
}

.drop-icon-1748000000 {
  font-size: 48px;
  margin-bottom: 10px;
  animation: bounce-1748000000 0.8s infinite alternate;
}

@keyframes bounce-1748000000 {
  from { transform: translateY(0); }
  to { transform: translateY(-10px); }
}

.drop-text-1748000000 {
  color: #fff;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.product-image-1748000000 {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}

.image-drop-zone-1748000000:hover .product-image-1748000000 {
  transform: scale(1.04);
}

/* Product Info */
.product-info-1748000000 {
  padding: 24px;
}

.product-name-1748000000 {
  font-size: 20px;
  font-weight: 700;
  color: #1a1a2e;
  margin-bottom: 10px;
  line-height: 1.3;
  outline: none;
  border-radius: 6px;
  padding: 2px 4px;
  transition: background 0.2s;
}

.product-name-1748000000:focus {
  background: #f0f0ff;
}

.product-desc-1748000000 {
  font-size: 14px;
  color: #666;
  line-height: 1.6;
  margin-bottom: 16px;
  outline: none;
  border-radius: 6px;
  padding: 2px 4px;
  transition: background 0.2s;
}

.product-desc-1748000000:focus {
  background: #f0f0ff;
}

.product-meta-1748000000 {
  margin-bottom: 16px;
}

.rating-1748000000 {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stars-1748000000 {
  color: #f5a623;
  font-size: 16px;
  letter-spacing: 2px;
}

.review-count-1748000000 {
  font-size: 13px;
  color: #999;
}

.price-row-1748000000 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}

.price-1748000000 {
  font-size: 26px;
  font-weight: 800;
  color: #1a1a2e;
}

.original-price-1748000000 {
  font-size: 16px;
  color: #bbb;
  text-decoration: line-through;
}

.discount-badge-1748000000 {
  background: #ffe0e0;
  color: #e53935;
  font-size: 16px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 12px;
}

.card-actions-1748000000 {
  display: flex;
  gap: 12px;
  align-items: center;
}

.btn-cart-1748000000 {
  flex: 1;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: #fff;
  border: none;
  border-radius: 14px;
  padding: 14px 20px;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 6px 20px rgba(102,126,234,0.4);
}

.btn-cart-1748000000:hover {
  opacity: 0.9;
  transform: translateY(-2px);
  box-shadow: 0 10px 28px rgba(102,126,234,0.5);
}

.btn-cart-1748000000:active {
  transform: scale(0.97);
}

.btn-cart-1748000000.added-1748000000 {
  background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%);
  box-shadow: 0 6px 20px rgba(67,233,123,0.4);
}

.btn-wishlist-1748000000 {
  width: 68px;
  height: 68px;
  border-radius: 16px;
  border: 2px solid #eee;
  background: #fff;
  font-size: 30px;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.btn-wishlist-1748000000:hover {
  border-color: #e53935;
  background: #fff5f5;
  transform: scale(1.1);
}

.btn-wishlist-1748000000.liked-1748000000 {
  border-color: #e53935;
  background: #fff5f5;
  color: #e53935;
}

